from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(float)
# try to locate exact boundary around flame x=135..160, top and bottom via red saturation. Print masks as bbox per row
r,g,b=im[...,0],im[...,1],im[...,2]
mask=(r>g*1.25+5)&(r>b*1.45+4)&((r-b)>30)
for y in range(0,110,2):
 xs=np.where(mask[y,100:200])[0]+100
 if len(xs): print(y, xs.min(), xs.max(), len(xs), 'groups', end=' ')
 else: print(y,'-',end=' ')
 # groups
 groups=[]
 for x in xs:
  if not groups or x>groups[-1][-1]+1:groups.append([x])
  else:groups[-1].append(x)
 print([(a[0],a[-1]) for a in groups])
PY"
